<script setup>
import {computed} from 'vue'
import {consultarIndicador,formatarTaxa,criarCSV} from '../../shared/indicadores.js'
import {useIndicador} from '../composables/useIndicador.js'
import EstadoDados from '../components/EstadoDados.vue'
import GraficoLinha from '../components/GraficoLinha.vue'
const props=defineProps({codigo:{type:String,required:true}})
const item=computed(()=>consultarIndicador(props.codigo))
const {serie,carregando,erro,aviso,consultaEm,carregar}=useIndicador(()=>item.value?.codigo)
const recente=computed(()=>serie.value.at(-1)),anterior=computed(()=>serie.value.at(-2))
const diferenca=computed(()=>recente.value && anterior.value?recente.value.valor-anterior.value.valor:null)
function exportar(){if(!serie.value.length)return;const url=URL.createObjectURL(new Blob([criarCSV(serie.value)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`rumocerto-${props.codigo}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><div class="container inner-page" v-if="item"><RouterLink to="/indicadores" class="back-link">← Voltar aos indicadores</RouterLink><div class="page-heading"><span class="eyebrow">BANCO MUNDIAL / OIT / MOÇAMBIQUE</span><h1>{{item.titulo}} — {{item.etiqueta.toLowerCase()}}</h1><p>{{item.descricao}}</p></div><p v-if="aviso" class="stale-note" role="status">{{ aviso }}</p><EstadoDados :carregando="carregando" :erro="erro" :vazio="!serie.length" @repetir="carregar(true)"/><template v-if="!carregando && !erro && serie.length"><div class="stat-strip"><article><span>Último valor disponível</span><strong>{{formatarTaxa(recente.valor)}}</strong><small>Ano {{recente.ano}}</small></article><article><span>Variação anual</span><strong>{{diferenca===null?'—':`${diferenca>0?'+':''}${diferenca.toFixed(1)} pp`}}</strong><small>Face ao ano anterior disponível</small></article><article><span>Observações</span><strong>{{serie.length}}</strong><small>{{serie[0].ano}}–{{recente.ano}}</small></article></div><section class="surface chart-section"><div class="section-heading"><div><span class="eyebrow">EVOLUÇÃO</span><h2>Últimas 12 observações disponíveis</h2></div><div class="chart-controls"><button class="text-button" @click="carregar(true)">Actualizar ↻</button><button class="text-button" @click="exportar">Descarregar CSV ↓</button></div></div><GraficoLinha :serie="serie"/><p class="source-caption" v-if="consultaEm">Consulta mais recente: {{new Date(consultaEm).toLocaleString('pt-MZ')}}</p></section></template><details class="info-disclosure detail-source"><summary>Fonte e metodologia <span aria-hidden="true">+</span></summary><div class="info-disclosure-content"><p>Banco Mundial, API de Indicadores, país MOZ, série <code>{{item.codigo}}</code>. Fonte primária: OIT, estimativas modeladas. A taxa refere-se à força de trabalho dos 15 aos 24 anos e não descreve situações individuais.</p><a class="text-link" :href="`https://data.worldbank.org/indicator/${item.codigo}?locations=MZ`" target="_blank" rel="noopener noreferrer">Consultar os dados oficiais ↗</a></div></details></div><div class="container inner-page" v-else><h1>Indicador não encontrado</h1><RouterLink to="/indicadores" class="btn btn-primary">Ver indicadores</RouterLink></div></template>
